source("pre.R")
x <- int64(c(-2, 5, -2, -1, NA)); df <- data.frame(k = x, a = 1:5)
show("aggregate formula", aggregate(a ~ k, df, sum))
show("aggregate formula na.pass", aggregate(a ~ k, df, sum, na.action = na.pass))
show("aggregate.data.frame", aggregate(df["a"], by = list(k = df$k), FUN = sum))
show("model.frame", {m <- model.frame(a ~ k, df); list(class(m$k), m)})
show("na.omit df", na.omit(df)); show("complete.cases", complete.cases(df)); show("is.na(df)", is.na(df))
show("na.omit vec", na.omit(x)); show("anyNA(df)", anyNA(df)); show("which(is.na(df$k))", which(is.na(df$k)))
show("xtabs", xtabs(a ~ k, df)); show("by()", by(df$a, df$k, sum)); show("ave", ave(df$a, df$k)); show("interaction", interaction(df$k, df$a > 2)); show("table 2d", table(df$k, df$a > 2, useNA="ifany"))
show("order 2 keys", order(c(1,1,1,1,1), x)); show("sort_by", tryCatch(sort_by(df, ~k), error=function(e) conditionMessage(e)))
show("rowsum", rowsum(df$a, df$k)); show("cut", cut(x, c(-3, 0, 10))); show("findInterval", findInterval(x, c(-3, 0, 10))); show("tabulate", tryCatch(tabulate(int64(c(1,2,2))), error=function(e) conditionMessage(e)))
show("u64 na.omit", na.omit(data.frame(k = uint64(c("18446744073709551614", NA, "1")))))
show("dec na.omit", na.omit(data.frame(k = decimal128(c("-1.5", NA, "1"), 10, 2))))
show("i128 aggregate.df", aggregate(data.frame(a=1:4), by = list(k = int128(c(-2, 5, -2, NA))), FUN = sum))
show("dec aggregate", aggregate(a ~ k, data.frame(k = decimal128(c("-1.5", "2", "-1.5"), 10, 2), a = 1:3), sum))
show("stats::median df", sapply(list(x), median, na.rm = TRUE)); show("range df", range(df$k, na.rm = TRUE)); show("summary df", summary(df))
show("diff/cumsum in df", within(df, c <- cumsum(a)))
show("quantile", tryCatch(quantile(x, na.rm=TRUE), error = function(e) class(e)[1])); show("var/sd", tryCatch(c(var(x[1:4]), sd(x[1:4])), error=function(e) conditionMessage(e))); show("cor", tryCatch(cor(x[1:4], 1:4), error=function(e) conditionMessage(e)))
show("weighted.mean", weighted.mean(x[1:4], c(1,1,1,1))); show("scale", tryCatch(scale(x), error=function(e) class(e)[1])); show("mad", tryCatch(mad(x[1:4]), error=function(e) conditionMessage(e)))
show("fivenum", tryCatch(fivenum(x), error=function(e) conditionMessage(e))); show("IQR", tryCatch(IQR(x[1:4]), error=function(e) class(e)[1])); show("boxplot.stats", tryCatch(boxplot.stats(x[1:4])$stats, error=function(e) class(e)[1]))
show("rowSums", tryCatch(rowSums(df), error=function(e) conditionMessage(e))); show("lm", tryCatch(coef(lm(a ~ k, df)), error=function(e) conditionMessage(e)))
show("plot range pretty", tryCatch(pretty(x[1:4]), error=function(e) conditionMessage(e))); show("hist", tryCatch(hist(x[1:4], plot=FALSE)$counts, error=function(e) conditionMessage(e)))
show("as.numeric(df$k)", as.numeric(df$k)); show("is.numeric", is.numeric(x)); show("mean", mean(x, na.rm=TRUE)); show("var int", var(as.numeric(x[1:4])))
